mapper.sql:
WHERE SBJ.DELYN = 'N'

  AND CHRT.ORG_ID = #{orgId}


  AND SBJ.SBJCT_YR = #{haksaYear}


  AND SBJ.SBJCT_SMSTR = #{haksaTerm}


  AND SBJ.SBJCT_ID = #{sbjctId}


  AND (
      LOWER(TO_CHAR(SBJ.CRCLMN_NO)) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
   OR LOWER(SBJ.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
   OR LOWER(NVL(PROF.USERNM, SBJ.PROF_ID)) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
  )

WHERE SBJ.DELYN = 'N'

  AND CHRT.ORG_ID = #{orgId}


  AND SBJ.SBJCT_YR = #{dgrsYr}


  AND SBJ.SBJCT_SMSTR = #{dgrsSmstrChrt}


  AND SBJ.SBJCT_ID = #{sbjctId}


  AND (
      LOWER(TO_CHAR(SBJ.CRCLMN_NO)) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
   OR LOWER(SBJ.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
   OR LOWER(NVL(PROF.USERNM, SBJ.PROF_ID)) LIKE FN_LIKE_VAL(LOWER(#{searchText}))
  )

mapper.select:
SELECT SBJ2.SBJCT_ID AS "sbjctId" , NVL(TO_CHAR(SBJ2.DVCLAS_NO), '-') AS "dvclasNo" FROM TB_LMS_SBJCT SBJ JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJ.SBJCT_REF_TYCD = 'SMSTR_CHRT' AND SBJ.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_SBJCT SBJ2 ON SBJ2.DELYN = 'N' AND SBJ2.SBJCT_REF_TYCD = SBJ.SBJCT_REF_TYCD AND SBJ2.SMSTR_CHRT_ID = SBJ.SMSTR_CHRT_ID AND NVL(SBJ2.CRCLMN_NO, ' ') = NVL(SBJ.CRCLMN_NO, ' ') AND SBJ2.SBJCTNM = SBJ.SBJCTNM AND ( (SBJ.DVCLAS_GRPCD IS NOT NULL AND SBJ2.DVCLAS_GRPCD = SBJ.DVCLAS_GRPCD) OR SBJ.DVCLAS_GRPCD IS NULL ) WHERE SBJ.DELYN = 'N' AND SBJ.SBJCT_ID = #{sbjctId}
AND CHRT.ORG_ID = #{orgId}
ORDER BY NVL(SBJ2.DVCLAS_NO, 99999) , SBJ2.SBJCT_ID

mapper.update:
MERGE INTO TB_LMS_MRK_ITM_STNG T
USING (
    SELECT
      #{sbjctId} AS SBJCT_ID
    , #{mrkItmTycd} AS MRK_ITM_TYCD
    FROM DUAL
) S
ON (
    T.SBJCT_ID = S.SBJCT_ID
    AND T.MRK_ITM_TYCD = S.MRK_ITM_TYCD
)
WHEN MATCHED THEN UPDATE SET
  T.MRK_RFLTRT = #{mrkRfltrt}
, T.MRK_OYN = #{mrkOyn}
, T.MRK_ITM_USEYN = #{mrkItmUseyn}
, T.MDFR_ID = #{mdfrId}
, T.MOD_DTTM = FN_DTTM()
WHEN NOT MATCHED THEN INSERT (
  MRK_ITM_STNG_ID
, SBJCT_ID
, MRK_ITM_TYCD
, MRK_RFLTRT
, MRK_OYN
, RGTR_ID
, REG_DTTM
, MDFR_ID
, MOD_DTTM
, MRK_ITM_USEYN
) VALUES (
  #{mrkItmStngId}
, #{sbjctId}
, #{mrkItmTycd}
, #{mrkRfltrt}
, #{mrkOyn}
, #{rgtrId}
, FN_DTTM()
, #{mdfrId}
, FN_DTTM()
, #{mrkItmUseyn}
)
